"""Generate canonical Atari task IDs from the pinned official ALE manifest.

Usage:
    python third_party/ale/generate_task_catalog.py /path/to/ale-0.11.2 \
        envpool/atari/task_catalog.h

The source is src/ale/python/roms/md5.json in Farama's ALE v0.11.2.
Its digest is checked so upgrading ALE cannot silently renumber task IDs.
"""

import argparse
import hashlib
import json
from pathlib import Path

_MANIFEST_SHA256 = (
    "3f1cdf2329541756248f0378ac406dacd9a0818e7abd73c13c6e8b14289cdf5e"
)
# Matches third_party/atari_roms/atari_roms.BUILD's single-player exclusions.
_UNSUPPORTED = {"combat", "joust", "maze_craze", "warlords"}


def main() -> None:
    """Verify the manifest and emit a stable, sorted native catalog."""
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("ale_source", type=Path)
    parser.add_argument("output", type=Path)
    args = parser.parse_args()
    manifest = args.ale_source / "src/ale/python/roms/md5.json"
    data = manifest.read_bytes()
    if hashlib.sha256(data).hexdigest() != _MANIFEST_SHA256:
        raise ValueError("Expected the unmodified ALE v0.11.2 ROM manifest")
    names = sorted(
        Path(name).stem
        for name in json.loads(data)
        if Path(name).stem not in _UNSUPPORTED
    )
    entries = "\n".join(f'    "{name}",' for name in names)
    args.output.write_text(
        "// Generated by third_party/ale/generate_task_catalog.py.\n"
        "// Source: Farama-Foundation/Arcade-Learning-Environment v0.11.2\n"
        "// src/ale/python/roms/md5.json. Do not reorder existing task IDs.\n"
        "// Copyright 2026 Garena Online Private Limited\n"
        "// SPDX-License-Identifier: Apache-2.0\n\n"
        "#ifndef ENVPOOL_ATARI_TASK_CATALOG_H_\n"
        "#define ENVPOOL_ATARI_TASK_CATALOG_H_\n\n"
        "#include <array>\n"
        "#include <string_view>\n\n"
        "namespace atari {\n\n"
        f"inline constexpr std::array<std::string_view, {len(names)}> "
        "kAtariTaskNames = {{\n"
        f"{entries}\n"
        "}};\n\n"
        "}  // namespace atari\n\n"
        "#endif  // ENVPOOL_ATARI_TASK_CATALOG_H_\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
